import type {
  SignatureProjectPricing,
  CanvassingProjectPricing,
  CanvassingUpcomingCanvasserPricing,
  CanvassingUpcomingManagerPricing,
  SignatureUpcomingCanvasserPricing,
  SignatureUpcomingManagerPricing,
} from '~/client';

export function projectPricing(pricing: SignatureProjectPricing | CanvassingProjectPricing) {
  if (isSignaturePricing(pricing)) {
    return `$${pricing.for_canvasser_per_signature}`;
  } else if (isCanvassingPricing(pricing)) {
    return `$${pricing.for_canvasser_per_hour}`;
  }
}

export function upcomingProjectPricing(
  pricing:
    | SignatureUpcomingManagerPricing
    | SignatureUpcomingCanvasserPricing
    | CanvassingUpcomingCanvasserPricing
    | CanvassingUpcomingManagerPricing
) {
  if (isUpcomingSignatureProjectPricing(pricing)) {
    return `$${pricing.for_canvasser_per_signature}`;
  } else if (isUpcomingCanvassingProjectPricing(pricing)) {
    return `$${pricing.for_canvasser_per_hour}`;
  }
}
